 680	 \subsection{Combining the $X$ and $Z$ measurements}
 681	\label{sec:combining}
 682	
 683	In this section our goal is to create a set of combined measurements
 684	that simultaneously measure the approximately-commuting measurements
 685	constructed in the previous section. We do this first for the points.
 686	Recall that $\mH_\alice$ and $\mH_\bob$ denote the Hilbert spaces corresponding to
 687	registers $\alice$ and $\bob$, respectively.
 688	
 689	\begin{lemma}\label{lem:qld-4-10}
 690	There exists a function $\delta_Q(\eps) = \poly(\eps)$ such that the following holds. 
 691		For every $x,z \in \F_q^m$ and $\mH \in \{ \mH_\alice, \mH_\bob\}$ there are projective measurements $\{ \hat{Q}^{x,z}_{a,b} \}_{a,b \in \F_q}$ acting on $\mathcal{H} \otimes (\C^q)^{\otimes \nqubits}$ such that:
 692		\begin{enumerate}
 693			\item (\textbf{Self-consistency}) On average over uniformly random $x,z \in \F_q^m$,
 694			\begin{equation}
 695				\label{eq:qld-q-self-cons}
 696				(\hat{Q}^{x,z}_{a,b})_{\alice \alice'}  \approx_{\delta_Q} (\hat{Q}^{x,z}_{a,b})_{\bob \alice''}\,.
 697			\end{equation}
 698			
 699			\item (\textbf{Consistency with $\hat{M}$}) On average over uniformly random $x,z \in \F_q^m$,
 700			\begin{gather}
 701				\label{eq:qld-q-cons-m-hat-xz}
 702					(\hat{Q}^{x,z}_{a,b})_{\alice \alice'} \approx_{\delta_Q} (\hat{M}^{(\Point,X),x}_{a} \hat{M}^{(\Point,Z),z}_b)_{\bob \alice''}\;, \\
 703								\label{eq:qld-q-cons-m-hat-zx}
 704					(\hat{Q}^{x,z}_{a,b})_{\alice \alice'} \approx_{\delta_Q} (\hat{M}^{(\Point,Z),z}_b  \hat{M}^{(\Point,X),x}_{a} )_{\bob \alice''}\;.
 705			\end{gather}
 706	              \end{enumerate}
 707	                    Furthermore, all symmetric equivalents of these approximations
 708	      also hold.
 709	\end{lemma}
 710	
 711	The construction of the measurements $\{ \hat{Q}^{x,z}_{a,b} \}$ whose existence is guaranteed in the lemma proceeds in three steps. In the first step, for every $(r,s)\in\F_q^2$ we combine the binary-outcome measurements $\hat{M}^{(\Point,X),x,r}_a$ and $\hat{M}^{(\Point,X),z,s}_b$; this is made possible by their approximate commutation as shown in Lemma~\ref{lem:qld-comm-cons}. In a second step, we show that the measurements thus constructed have a particular ``approximate linearity'' property, when seen as a function of the pair $(r,s)$. This allows us, in the third step, to combine them into a single measurement $\{ \hat{Q}^{x,z}_{a,b} \}$ with outcomes in $\F_q^2\cong \F_2^{2t}$ by applying the following  result from~\cite{NV17}:
 712		
 713		\begin{theorem}[Quantum linearity test]
 714		\label{thm:linearity}
 715			Let $0 \leq \delta \leq 1$, let $t$ be a positive integer, and let $\ket{\psi}$ be a state in a Hilbert space $\mathcal{H}_\alice \otimes \mathcal{H}_\bob$. Let $\{\mathcal{O}^u \}$ be a set of observables indexed by $u \in \F_2^t$ that act on $\mathcal{H}_\alice$. Suppose that on average over $u, u'$ chosen uniformly from $\F_2^t$, we have the following ``approximate linearity'' holds:
 916		\Big ( \hat{Q}^{x,z}_{a} \Big)_{\alice \alice'} \approx_{\delta_Q} \Big (\hat{M}^{(\Point,X),x}_{a} \Big)_{\bob \alice''} \;.
 917		\end{equation}
 918		This follows from~\eqref{eq:qqm} and the following calculation:
 919		\begin{align*}
 920			&\E_{x,z} \sum_a \norm{ \sum_b  \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} \cdot \Big ( \hat{M}^{(\Point,\zpt),z}_{b} \Big)_{\bob \alice''} - \Big ( \hat{M}^{(\Point,\xpt),x}_{a} \Big)_{\bob \alice''}  \ket{\hat{\psi}} }^2  \\
 921			&=\E_{x,z} \sum_a \norm{ \sum_b \Big ( \hat{M}^{(\Point,\zpt),z}_{b} \Big)_{\bob \alice''} \cdot  \Big( \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} - \Big ( \hat{M}^{(\Point,\xpt),x}_{a} \Big)_{\bob \alice''}  \Big) \ket{\hat{\psi}} }^2  \\
 922			&= \E_{x,z} \sum_{a,b}  \norm{  \Big ( \hat{M}^{(\Point,\zpt),z}_{b} \Big)_{\bob \alice''} \cdot  \Big( \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} - \Big ( \hat{M}^{(\Point,\xpt),x}_{a} \Big)_{\bob \alice''}  \Big) \ket{\hat{\psi}} }^2  \\
 923	                &= \E_{x,z} \sum_{a,b} \norm{ \Big(  \hat{M}^{(\Point,\zpt),z}_{b} \Big)_{\bob \alice''} \cdot  \Big( \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} - \Big( \hat{M}^{(\Point, \zpt),z}_{b} \cdot \hat{M}^{(\Point,\xpt),x}_{a} \Big)_{\bob \alice''}  \Big) \ket{\hat{\psi}} }^2  \\
 924	                &\leq \E_{x,z} \sum_{a,b} \norm{ \Big( \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} - \Big( \hat{M}^{(\Point, \zpt),z}_{b} \cdot \hat{M}^{(\Point,\xpt),x}_{a} \Big)_{\bob \alice''}  \Big) \ket{\hat{\psi}} }^2  \\
 925			&= O(\delta)\;,
 926		\end{align*} 
 927		where the second line uses the property $\sum_b \hat{M}^{(\Point,\zpt),z}_b = I$, the third and fourth lines uses the projectivity of $\{ \hat{M}^{(\Point,\zpt),z}_{b} \}$, the fifth line uses $\hat{M}^{(\Point, \zpt), z}_{b} \leq I$, and the last line uses \Cref{eq:qld-q-cons-m-hat-zx}. This shows~\eqref{eq:qld-qxz-close-to-point}. A similar argument shows that
 928		\begin{equation}\label{eq:qld-qxz-close-to-point-2}
 929		\Big ( \hat{Q}^{x,z}_{b} \Big)_{\alice \alice'} \approx_{\delta_Q} \Big (\hat{M}^{(\Point,Z),z}_{b} \Big)_{\bob \alice''}\;.
 930		\end{equation}
 931		Next, from Lemma~\ref{lem:qld-comm-line-cons} we get that on average over $(\line_X,x)$ and $(\line_Z,z)$ sampled independently from the line-point distribution (\Cref{def:line-point-dist}),
 932		\begin{gather}
 933		(\hat{M}^{(\Line,X),\line_\xpt}_{[\eval_x(\cdot) = a]})_{\bob \alice''} \approx_\delta  (\hat{M}^{(\Point,\xpt),x}_{a})_{\bob \alice''} \;,\\
 934		( \hat{M}^{(\Line,Z),\line_\zpt}_{[\eval_z(\cdot) = b]})_{\bob \alice''} \approx_\delta  (\hat{M}^{(\Point,\zpt),z}_{b})_{\bob \alice''}\;.
 935		\end{gather}
 936		where we used both the self-consistency of the line measurements (item 1 in Lemma~\ref{lem:qld-comm-line-cons}) as well as their consistency with the points measurements (item 3). To deduce both of these relations, we used \Cref{fact:agreement} to convert between $\approx$ and $\simeq$ distance, and \Cref{fact:data-processing} to sum over outcomes to the lines measurement. Since the $\{\hat{M}^{(\Line,W),\line}_f \}$ and $\{ \hat{Q}^{x,z}_{a,b} \}$ are projective, together with~\eqref{eq:qld-qxz-close-to-point} and~\eqref{eq:qld-qxz-close-to-point-2}
 937		by Fact~\ref{fact:agreement} we get
 938		\begin{align}\label{eq:pasting-q1}
 939			\Big ( \hat{Q}^{x,z}_{a} \Big)_{\alice \alice'} \simeq_{\delta_Q} \Big (\hat{M}^{(\Line,\xpt),\line_\xpt}_{[\eval_x(\cdot) = a]} \Big)_{\bob \alice''} \qquad \text{and} \qquad \Big ( \hat{Q}^{x,z}_{b} \Big)_{\alice \alice'} \simeq_{\delta_Q} \Big (\hat{M}^{(\Line,\zpt),\line_\zpt}_{[\eval_z(\cdot) = b]} \Big )_{\bob \alice''} \;.
 940		\end{align}
